async runSeed(connection, loaded) {
    const mode = loaded.seed.transaction ?? 'auto';
    if (mode === false) {
        const context = createSeedContext(connection, this.options.config, this.options.container);
        const startedAt = Date.now();
        await loaded.seed.run(context);
        await recordSeedCompleted(context.connection, {
            tableName: this.options.tableName,
            packageName: loaded.packageName,
            name: loaded.name,
            checksum: loaded.checksum,
            durationMs: Date.now() - startedAt,
        });
        return;
    }
    await connection.transaction(async (trxConnection) => {
        const context = createSeedContext(trxConnection, this.options.config, this.options.container);
        const startedAt = Date.now();
        await loaded.seed.run(context);
        await recordSeedCompleted(context.connection, {
            tableName: this.options.tableName,
            packageName: loaded.packageName,
            name: loaded.name,
            checksum: loaded.checksum,
            durationMs: Date.now() - startedAt,
        });
    });
}

